using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Automation;

public static class FarmHomecomingTests
{
    private static void Check(bool ok,string text){if(!ok)throw new Exception("Homecoming: "+text);}
    private static FarmGame New(string root)
    {
        var g=new FarmGame(Path.Combine(root,"homecoming-"+Guid.NewGuid().ToString("N")+".xml"));g.S.LastFarmTicks=DateTime.UtcNow.AddDays(1).Ticks;g.S.BlessingOffers=new[]{0,1,2};return g;
    }
    private static FarmGame Ready(string root)
    {
        var g=New(root);g.S.Xp=Enumerable.Repeat(55,5).ToArray();g.S.GardenUnlocked=true;g.S.ExpeditionClears[0]=1;g.S.Harvests=1;g.S.Grain=27;g.S.Fertilizer=1;g.Save();return g;
    }
    public static string Run(string root)
    {
        var g=Ready(root);string original=FarmPracticeTests.Xml(g.S),disk=File.ReadAllText(g.SavePath);var q=g.QuoteHomecoming(true,true,true);
        Check(q.Cost.SequenceEqual(new[]{0,36,0,4,0})&&q.Gains.SequenceEqual(new[]{4,9,0,3,0})&&q.After[1]==0&&q.After[3]==0&&g.CanApplyHomecoming(q),"earned chapter rewards can fund exact training and soil costs");
        Check(FarmPracticeTests.Xml(g.S)==original&&File.ReadAllText(g.SavePath)==disk,"quotes and readiness checks perform no writes or state changes");
        g.S.Grain=26;string shortState=FarmPracticeTests.Xml(g.S);Check(!g.ApplyHomecoming(q)&&FarmPracticeTests.Xml(g.S)==shortState&&g.S.ChapterClaimed.All(x=>!x),"one missing grain rejects entire plan including claiming");
        g.S.Grain=27;g.S.Fertilizer=0;shortState=FarmPracticeTests.Xml(g.S);Check(!g.ApplyHomecoming(q)&&FarmPracticeTests.Xml(g.S)==shortState,"one missing fertilizer rejects entire plan");g.S.Fertilizer=1;
        g.S.Grain+=5;Check(g.HomecomingQuoteCurrent(q)&&g.ApplyHomecoming(q),"passive inventory growth does not stale confirmed costs");
        var r=g.S.LastHomecoming;Check(g.AtHome&&g.S.Grain==5&&g.S.Fertilizer==0&&g.S.Berries==14&&g.S.SoilLevel==1&&g.S.Team.All(p=>g.Level(p)==4&&g.S.Xp[p]==127),"selected steps apply with exact costs and retained XP remainder");
        Check(g.S.ChapterClaimed.Take(3).All(v=>v)&&!g.S.ChapterClaimed[3]&&g.ChapterDone(3),"newly completed soil chapter is not auto claimed");
        Check(r.Chapters==3&&r.Spent.SequenceEqual(new[]{0,36,0,4,0})&&r.BeforeLevels.All(n=>n==3)&&r.AfterLevels.All(n=>n==4)&&r.BeforeHp.Zip(r.AfterHp,(a,b)=>b-a).All(n=>n==6)&&r.BeforeAttack.Zip(r.AfterAttack,(a,b)=>b-a).All(n=>n==2),"receipt contains actual growth and costs");
        Check(r.RatesAfter.SequenceEqual(g.FarmRates())&&r.RatesAfter.Sum()>r.RatesBefore.Sum(),"receipt farm rates use actual plots and final soil");
        string after=FarmPracticeTests.Xml(g.S);Check(!g.ApplyHomecoming(q)&&FarmPracticeTests.Xml(g.S)==after,"same receipt cannot be executed twice");var loaded=new FarmGame(g.SavePath);Check(FarmPracticeTests.Xml(loaded.S.LastHomecoming)==FarmPracticeTests.Xml(r)&&loaded.S.Grain==5&&loaded.S.SoilLevel==1,"receipt persists without applying again on reload");
        string receipt=FarmPracticeTests.Xml(r);g.S.Xp[0]=300;g.S.SoilLevel=3;g.S.Crops[0]=1;g.Save();Check(FarmPracticeTests.Xml(g.S.LastHomecoming)==receipt,"later growth and planting never rewrite old receipt");
        var stale=Ready(root);var pending=stale.QuoteHomecoming(true,true,true);stale.S.Xp[0]+=18;after=FarmPracticeTests.Xml(stale.S);Check(!stale.ApplyHomecoming(pending)&&FarmPracticeTests.Xml(stale.S)==after,"changed training cost invalidates old plan");pending=stale.QuoteHomecoming(true,true,true);stale.S.Run=new FarmRun();Check(!stale.ApplyHomecoming(pending),"replaced journey state rejects old UI plan even at home");
        var empty=New(root);empty.S.Fertilizer=30;empty.S.Grain=100;Check(!empty.CanApplyHomecoming(empty.QuoteHomecoming(false,false,false)),"empty plan cannot apply");var rates=empty.FarmRates();var soil=empty.QuoteHomecoming(false,true,false);Check(empty.ApplyHomecoming(soil)&&empty.S.LastHomecoming.RatesBefore.SequenceEqual(rates)&&empty.S.LastHomecoming.RatesAfter.SequenceEqual(empty.FarmRates())&&!empty.S.GardenUnlocked,"locked plots never inflate soil preview");
        var max=Ready(root);max.S.SoilLevel=5;max.S.Xp[max.S.Team[0]]=1250;max.S.Grain=100;var training=max.QuoteHomecoming(false,false,true);Check(training.Cost[1]==24&&max.ApplyHomecoming(training)&&max.S.Xp[max.S.Team[0]]==1250&&max.S.Grain==76,"max-level pet skipped while others train one level");Check(!max.CanApplyHomecoming(max.QuoteHomecoming(false,true,false)),"max soil is unavailable");max.S.Xp=Enumerable.Repeat(1250,5).ToArray();Check(!max.CanApplyHomecoming(max.QuoteHomecoming(false,false,true)),"max-level party is unavailable");
        var caps=Ready(root);caps.S.Berries=99999;caps.S.Grain=Int32.MaxValue;caps.S.Mint=Int32.MaxValue;Check(caps.ApplyHomecoming(caps.QuoteHomecoming(true,false,false))&&caps.S.Berries==99999&&caps.S.Grain==Int32.MaxValue&&caps.S.Mint==Int32.MaxValue&&caps.S.LastHomecoming.Gained[0]==0&&caps.S.LastHomecoming.Gained[1]==0,"capped reward cannot overflow or reduce stored resources");
        var trip=Ready(root);trip.S.Grain=80;trip.PlanPicnic(0);trip.BeginJourney(0,0);trip.ToggleJourneyPause();var away=trip.QuoteHomecoming(true,true,true);after=FarmPracticeTests.Xml(trip.S);Check(!trip.ApplyHomecoming(away)&&FarmPracticeTests.Xml(trip.S)==after&&trip.R.JourneyPaused,"active paused trip rejects all homecoming changes");trip.ToggleJourneyPause();trip.AdvanceJourney(DateTime.UtcNow.AddHours(2));Check(trip.R.Outcome=="victory","result fixture returns");int fert=trip.S.Fertilizer,crystals=trip.S.Crystals;string history=FarmPracticeTests.Xml(trip.S.JourneyMemories);var paid=trip.QuoteHomecoming(false,true,true);int[] permanent=trip.S.Team.Select(trip.PermanentHp).ToArray();Check(trip.ApplyHomecoming(paid)&&trip.AtHome&&trip.S.Fertilizer==fert-paid.Cost[3]&&trip.S.Crystals==crystals&&FarmPracticeTests.Xml(trip.S.JourneyMemories)==history,"result returns home without repeating adventure loot or altering battles");Check(trip.S.LastHomecoming.BeforeHp.SequenceEqual(permanent)&&trip.R.Picnic==-1&&trip.R.Inspirations.All(n=>n==0),"receipt excludes temporary HP and returning clears travel effects");
        var backup=new FarmGame(trip.SavePath);Check(backup.S.LastHomecoming!=null&&backup.S.SoilLevel==trip.S.SoilLevel,"result and spending persist together");var xml=XDocument.Load(trip.SavePath);xml.Root.Element("LastHomecoming").Remove();string oldPath=Path.Combine(root,"before-homecoming.xml");xml.Save(oldPath);var old=new FarmGame(oldPath);Check(old.S.LastHomecoming==null&&old.S.Grain==trip.S.Grain,"old saves have no invented receipt");
        backup.S.LastHomecoming.Names=null;backup.Save();Check(backup.S.LastHomecoming==null&&new FarmGame(backup.SavePath).LoadWarning=="","malformed optional receipt is discarded without losing progress");
        return "PASS: pure quotes; exact combined budget; reward-before-spend; missing-resource atomic rejection; passive stock growth; stale/double-click guards; temporary/permanent stats; max levels; overflow/caps; active-trip locks; result loot and history preserved; old saves; persistent receipts; only open plots counted.";
    }
}

