        int grain=G.S.Grain;G.S.Grain=0;RefreshCounters();check(!UIAction("确认这次安排").IsEnabled,"insufficient grain disables combined confirmation live");ArrangementRender(root,"missing-small",764,571);
        var crops=(int[])G.S.Crops.Clone();UIAction("缺麦穗？看看种植方案").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"planting-small",764,571);UIVisible(UIAction("带着原安排返回"),"planting return fits minimum window");check(G.S.Crops.SequenceEqual(crops)&&arrangeClaim&&arrangeSoil&&arrangeTrain,"planting preview retains selection without replanting");var plant=UIChildren<Button>((DependencyObject)Content).First(b=>Convert.ToString(b.Content).StartsWith("应用方案"));plant.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"planting-applied");UIAction("带着原安排返回").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"planting-returned");check(arrangeClaim&&arrangeSoil&&arrangeTrain&&G.R.Phase=="result"&&G.S.SoilLevel==0&&G.S.ChapterClaimed.All(x=>!x),"planting return restores all choices without spending or dismissing result");UIAction("先不安排，回收获页").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"cancelled");check(G.R.Phase=="result"&&G.S.SoilLevel==0&&G.S.ChapterClaimed.All(x=>!x),"cancel preserves unspent result");
        G.S.Grain=grain;OpenHomecoming();arrangeSoil=arrangeTrain=true;ArrangementRender(root,"ready");G.S.Xp[0]++;RefreshCounters();check(!UIAction("确认这次安排").IsEnabled,"changed XP invalidates old display before confirmation");UIAction("刷新安排").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"refreshed");check(UIAction("确认这次安排").IsEnabled,"refresh adopts new exact costs");
        var oldButton=UIAction("确认这次安排");int fertilizer=G.S.Fertilizer;oldButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"receipt");ArrangementRender(root,"receipt-small",764,571);UIVisible(UIAction("重走「小溪 · 初探」"),"same route preparation visible in minimum receipt");UIVisible(UIAction("准备挑战「小溪 · 深入」"),"next depth preparation visible in minimum receipt");check(G.AtHome&&G.S.LastHomecoming!=null&&G.S.SoilLevel==1&&G.S.LastHomecoming.Spent[3]==4,"actual UI confirms combined plan and records receipt");string done=FarmPracticeTests.Xml(G.S);oldButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(FarmPracticeTests.Xml(G.S)==done,"detached double click cannot execute again");
        UIAction("准备挑战「小溪 · 深入」").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"next-depth");check(Tab=="冒险"&&G.AtHome&&journeyDifficulty==0&&journeyDepth==1&&G.S.PlannedPicnic==-1,"next depth opens preparation without departure or food charge");
        OpenHomecoming(true);ArrangementRender(root,"reopened-receipt");string receipt=FarmPracticeTests.Xml(G.S.LastHomecoming);check(FarmPracticeTests.Xml(new FarmGame(G.SavePath).S.LastHomecoming)==receipt,"saved receipt reload matches actual UI");
        G.BeginJourney(0,G.S.BlessingOffers[0]);G.ToggleJourneyPause();OpenHomecoming();ArrangementRender(root,"away");check(G.R.JourneyPaused&&!UIChildren<Button>((DependencyObject)Content).Any(b=>Convert.ToString(b.Content)=="确认这次安排"),"paused travel has no spending action");UIAction("上次安排的记录").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));ArrangementRender(root,"away-receipt");check(!UIAction("重走「小溪 · 初探」").IsEnabled&&G.R.JourneyPaused&&FarmPracticeTests.Xml(G.S.LastHomecoming)==receipt,"old receipt remains readable but cannot start or unpause a trip");
        G.Retreat();G.Home();G.S.Xp=Enumerable.Repeat(1250,5).ToArray();G.S.SoilLevel=5;G.ClaimReadyChapters();OpenHomecoming();ArrangementRender(root,"maxed");check(!ArrangementToggle("升级一次土壤").IsEnabled&&!ArrangementToggle("出战伙伴各升一级").IsEnabled&&!UIAction("确认这次安排").IsEnabled,"completed upgrade paths do not offer empty spending");
        check(!IsVisible&&!owner.IsVisible,"homecoming never opens native windows");File.WriteAllText(Path.Combine(root,"homecoming-ui-regression.txt"),"PASS: result entry; preview-only toggles; cancel; live shortfall; stale quote refresh; minimum-window confirmation and route actions; exact application; double-click guard; persisted receipt; next-depth preparation only; paused-trip readonly; capped progression. Isolated saves and offscreen rendering.");
    }
}
